-- V1: users + user_settings.
-- Portable SQL: runs on PostgreSQL and on H2 in PostgreSQL compatibility mode.
-- IDs are generated by Hibernate (@UuidGenerator), not by the database.
CREATE TABLE users (
    id            UUID NOT NULL,
    email         VARCHAR(254) NOT NULL,
    password_hash TEXT NOT NULL,
    display_name  VARCHAR(80),
    timezone      VARCHAR(64) NOT NULL,
    created_at    TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at    TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_users PRIMARY KEY (id),
    CONSTRAINT uq_users_email UNIQUE (email)
);

CREATE TABLE user_settings (
    user_id           UUID NOT NULL,
    week_starts_on    SMALLINT NOT NULL DEFAULT 1, -- 1=Mon .. 7=Sun
    reminders_enabled BOOLEAN NOT NULL DEFAULT FALSE,
    CONSTRAINT pk_user_settings PRIMARY KEY (user_id),
    CONSTRAINT fk_user_settings_user FOREIGN KEY (user_id)
        REFERENCES users (id) ON DELETE CASCADE
);
